		"CREATE TABLE {$p}interactions (id bigint unsigned NOT NULL AUTO_INCREMENT,user_id bigint unsigned NOT NULL,video_id bigint unsigned NOT NULL,interaction varchar(32) NOT NULL,created_at datetime NOT NULL,updated_at datetime NOT NULL,PRIMARY KEY(id),UNIQUE KEY user_video_type(user_id,video_id,interaction),KEY video_type(video_id,interaction)) $c",
