		"CREATE TABLE {$p}audit (id bigint unsigned NOT NULL AUTO_INCREMENT,public_id varchar(80) NOT NULL,object_type varchar(32) NOT NULL,object_id varchar(80) NOT NULL,action varchar(64) NOT NULL,previous_state varchar(32) NULL,new_state varchar(32) NULL,actor_id bigint unsigned NOT NULL DEFAULT 0,purpose varchar(64) NOT NULL DEFAULT 'platform_operation',trace_id varchar(80) NOT NULL,note longtext NULL,meta_json longtext NULL,created_at datetime NOT NULL,PRIMARY KEY(id),UNIQUE KEY public_id(public_id),KEY object_action(object_type,object_id,action),KEY actor_created(actor_id,created_at),KEY trace_id(trace_id)) $c",
