		"CREATE TABLE {$p}webhooks (id bigint unsigned NOT NULL AUTO_INCREMENT,public_id varchar(80) NOT NULL,provider varchar(64) NOT NULL,event_id varchar(191) NOT NULL,event_type varchar(100) NOT NULL,signature_hash varchar(128) NULL,payload_hash varchar(128) NOT NULL,payload_json longtext NOT NULL,status varchar(32) NOT NULL DEFAULT 'received',attempts int unsigned NOT NULL DEFAULT 0,received_at datetime NOT NULL,processed_at datetime NULL,error_message text NULL,PRIMARY KEY(id),UNIQUE KEY public_id(public_id),UNIQUE KEY provider_event(provider,event_id),KEY queue(status,received_at)) $c",
